from pathlib import Path
from io import BytesIO
import sys,json,html
import cairosvg
from PIL import Image
OUT=Path(sys.argv[1]);OUT.mkdir(parents=True,exist_ok=True);checks=[];names=[]
def render(n,body):
 names.append(n);s='<svg xmlns="http://www.w3.org/2000/svg" width="280" height="170">'+body+'<rect x="240" y="20" width="20" height="60" fill="blue"/></svg>';(OUT/(n+'.svg')).write_text(s);p=cairosvg.svg2png(bytestring=s.encode());(OUT/(n+'.png')).write_bytes(p);return Image.open(BytesIO(p)).convert('RGBA')
cases=[('positive-negative','filterUnits="userSpaceOnUse" x="0" y="0" width="200" height="150"','<feOffset dx="15" dy="-5"/>','<rect x="10" y="20" width="40" height="20" fill="red" filter="url(#f)"/>','<rect x="25" y="15" width="40" height="20" fill="red"/>'),('non-square-bbox','filterUnits="userSpaceOnUse" primitiveUnits="objectBoundingBox" x="0" y="0" width="200" height="150"','<feOffset dx=".25" dy="-.25"/>','<rect x="20" y="30" width="80" height="40" fill="red" filter="url(#f)"/>','<rect x="40" y="20" width="80" height="40" fill="red"/>'),('host-scale','filterUnits="userSpaceOnUse" x="0" y="0" width="200" height="150"','<feOffset dx="15" dy="-5"/>','<g transform="translate(5 0) scale(2)"><rect x="10" y="20" width="40" height="20" fill="red" filter="url(#f)"/></g>','<rect x="55" y="30" width="80" height="40" fill="red"/>'),('clipped-output','filterUnits="userSpaceOnUse" x="10" y="10" width="50" height="50"','<feOffset dx="30" dy="0"/>','<rect x="10" y="20" width="40" height="20" fill="red" filter="url(#f)"/>','<rect x="40" y="20" width="20" height="20" fill="red"/>')]
for n,attrs,primitive,host,reference in cases:
 a=render(n,'<defs><filter id="f" '+attrs+'>'+primitive+'</filter></defs>'+host);b=render(n+'-reference',reference);checks.append({'name':n+'-explicit-geometry','different_pixels':sum(x!=y for x,y in zip(a.getdata(),b.getdata())),'passed':a.tobytes()==b.tobytes()});checks.append({'name':n+'-blue-sibling','passed':a.getpixel((250,50))==(0,0,255,255)})
# Shadow and source are composed as declared, not by moving the live host context.
a=render('source-shadow','<defs><filter id="f" filterUnits="userSpaceOnUse" x="0" y="0" width="200" height="150"><feOffset dx="60" dy="0" result="shift"/><feMerge><feMergeNode in="shift"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><rect x="10" y="20" width="40" height="40" fill="red" opacity=".5" filter="url(#f)"/>');b=render('source-shadow-reference','<g opacity=".5"><rect x="10" y="20" width="40" height="40" fill="red"/><rect x="70" y="20" width="40" height="40" fill="red"/></g>');checks.append({'name':'source-and-offset-merge-with-opacity','passed':a.tobytes()==b.tobytes()})
r={'source':cairosvg.__file__,'tests':len(checks),'passed':sum(c['passed'] for c in checks),'failed':sum(not c['passed'] for c in checks),'checks':checks};(OUT/'result.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');print(json.dumps(r,ensure_ascii=False,indent=2));(OUT/'gallery.html').write_text('<!doctype html><meta charset="utf-8"><title>滤镜偏移与几何参考</title><style>body{font:20px system-ui;margin:24px}img{width:700px;border:1px solid #aaa;background:#eee}pre{white-space:pre-wrap}</style><h1>正负偏移、非方形bbox、外层缩放及区域裁切</h1>'+''.join('<h2>'+n+'</h2><p>SVG输入</p><img src="'+n+'.svg"><p>当次PNG</p><img src="'+n+'.png">' for n in names)+'<pre>'+html.escape(json.dumps(r,ensure_ascii=False,indent=2))+'</pre>');sys.exit(bool(r['failed']))
